@Component
public class SingletonService {

    // Business logic that requires a fresh PrototypeCommand on every invocation
    public void processTransaction(String payload) {
        PrototypeCommand command = getPrototypeCommand();
        command.execute(payload);
    }

    // Spring will override this method at runtime via a CGLIB proxy
    @Lookup
    protected PrototypeCommand getPrototypeCommand() {
        // The return value here is immaterial; Spring's method interceptor overrides it.
        return null;
    }
}

@Component
@Scope("prototype")
public class PrototypeCommand {
    private final String id = UUID.randomUUID().toString();

    public void execute(String payload) {
        System.out.println("Executing command " + id + " with payload: " + payload);
    }
}
